import{_ as n,P as a,d as s,e as r,x as t,q as i}from"./chunks/framework.BRr8VP3a.js";const b=JSON.parse('{"title":"Part 14 Normative Choice","description":"","frontmatter":{"title":"Part 14 Normative Choice","xkChars":0,"xkWords":6250,"xkLessons":{"14.4.1":{"title":"Trace affected positions proportionately without shrinking protection","lead":"A stopping rule for further inquiry is not a license to omit known people or lower their safeguards.","explanation":["Directly affected positions, known or raised low-power positions, and positions explicitly required by the application module must be listed in full. Proportionality governs the further tracing of indirect and more distant effects, taking severity, irreversibility, scale, accumulation, and power differences into account.","Further tracing may stop when it can no longer reasonably change the judgment, comparison of options, or protection arrangements. Record channels searched, positions consulted, and remaining unknowns. Include an undeclared channel raised by others or state the reason for not adopting it. The grounds must be published in advance and open to appeal; a beneficiary of a narrow boundary cannot decide it alone, and high-impact cases or conflicts require independent review.","An unknown reasonably capable of revealing a failure of the protection floor or changing the option comparison blocks the affected part of adoption until evidence is added, the option is narrowed, or protection with separate grounds is in place. Other unknowns remain visible with observation and renewed-identification conditions. Later-discovered positions retain the same appeal, correction, and remedy rights without proving they were foreseeable."],"distinctions":[{"leftTitle":"Proportionate identification","leftText":"Limits further tracing of indirect and distant positions on explicit grounds.","rightTitle":"Protection of identified positions","rightText":"Is not reduced by that tracing limit."}],"teachingExamples":[{"title":"A service relocation and a missing user group","text":"Suppose direct users are listed and a low-power group is raised by an advocate. That group cannot be omitted because it is costly to contact. More remote effects may use the proportionate tracing rule, with the basis open to challenge.","assumptions":"Hypothetical proposal; no actual service or group is evaluated.","boundary":"Known harm cannot be left unprotected merely because all distant effects cannot be exhaustively mapped."}],"boundaries":["Do not apply the proportional stopping rule to the categories that must be fully listed.","Distinguish blocking unknowns from other registered unknowns; do not declare every gap harmless."],"questionAnswers":[{"question":"Are harms of keeping the status quo exempt from this inquiry?","answer":"No. No action and maintaining the status quo carry the same responsibility to identify affected positions.","basis":"Theory v2, §14.4.1, with the distinctions explained above."}],"caseLinks":[],"sourceRefs":[{"section":"14.4.1","startLine":3068,"endLine":3075}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-14#section-14-4-1","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§14.4.1; English reading edition, lines 3068–3075","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"14.5":{"title":"Past consent does not close every later route of refusal","lead":"Check the original choice and the current conditions for refusal, negotiation, and exit separately.","explanation":["An initial choice can alter later options through debt, interrupted skills, housing, services, or care dependencies. Continued participation then provides weaker evidence of continuing consent. A signature or failure to leave does not by itself establish that refusal is still safe and feasible.","This does not cancel bounded commitments or support duties with independent grounds, and it does not require every future option to remain open forever. The inquiry asks how the relevant obligation can be fulfilled, renegotiated, transferred, or ended under the applicable conditions.","Participation also has levels. An institution may respond to individual issues while its agenda, rules, or final adjudicator remain unchallengeable. Report both facts. In high-impact cases or conflicts, an unchallengeable final decision without external independent review does not satisfy N3 and PF-7."],"distinctions":[{"leftTitle":"Issue-level response","leftText":"A specific complaint may receive a reasoned answer or change.","rightTitle":"Adequate capacity for correction","rightText":"Also depends on the relevant rules, final authority, and available independent review."}],"teachingExamples":[{"title":"A choice changes later choices","text":"Suppose someone freely entered an arrangement, then housing and essential care became tied to staying. Their continued presence cannot alone establish present consent; current refusal and transition conditions require examination.","assumptions":"Constructed scenario, not a finding about a real relationship.","boundary":"It does not automatically cancel independently grounded obligations or justify unsafe withdrawal of support."}],"boundaries":["Do not fabricate unanimous consent from majority voting or formal participation.","A framework authorization record is not external legal authority."],"questionAnswers":[{"question":"Does an unresolved disagreement necessarily mean the process failed?","answer":"No. A reasoned response under a qualified decision rule can preserve disagreement. Unanswered decisive objections and failed protection conditions are different problems.","basis":"Theory v2, §14.5, with the distinctions explained above."}],"caseLinks":[{"title":"Democratic authorization and review","href":"/en/cases/democratic-authorization"}],"sourceRefs":[{"section":"14.5","startLine":3076,"endLine":3091}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-14#section-14-5","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§14.5; English reading edition, lines 3076–3091","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"14.9.1":{"title":"A choice with losses still calls for a reasoned bounded judgment","lead":"Recommend within explicit premises while preserving unmet claims and the limits of authority.","explanation":["Sometimes every feasible option, including delay and no action, leaves legitimate claims unmet. The analysis should not invent a costless option or stop at questions. It can give a recommendation for deliberation, with the normative premises and decision rule made explicit.","State who bears the remaining losses, why their claims still hold, who owes mitigation, remedy, explanation, or review, and what would change the recommendation. If the decision rule is disputed, present the different resulting judgments without choosing on behalf of a qualified authority.","First test the apparent lack of alternatives: who controls the scarcity, whether prior decisions can be challenged, and whether options were excluded merely because they cost the decision maker. If authority is insufficient, refer the matter to a subject with authority rather than treating that gap as proof of no alternative. This showing remains open to appeal and goes to review independent of the decision maker.","Nonwaivable law and protection do not lapse because choices are painful. A claim that they cannot all be preserved must identify the conflicting requirements and excluded options for independent review. If that claim is not confirmed, return to options that do not cross those requirements. Even if confirmed, the framework does not endorse any option as authorized, and still-preservable protections continue. A competent actor needs its own applicable statutory or emergency authority, acts within the narrowest scope, bears responsibility, and sets expiry and subsequent review."],"distinctions":[{"leftTitle":"Analytical recommendation","leftText":"A reasoned proposal with premises, costs, and revision conditions.","rightTitle":"Real-world authorization","rightText":"Valid authority and applicable protections for execution."}],"teachingExamples":[{"title":"Two urgent needs, one available worker","text":"Assume two needs compete for one worker and all feasible schedules cause some delay. A stated priority rule can support a bounded recommendation. The delayed person’s claim and the institution’s staffing responsibility remain on record.","assumptions":"Hypothetical scarcity; no clinical triage instruction is given.","boundary":"Actual professional or emergency decisions require the relevant competent procedure."}],"boundaries":["Costs of waiting do not create authority to act.","Nonwaivable requirements cannot be traded away by a framework score."],"questionAnswers":[{"question":"Does choosing an option erase the losses that could not be avoided?","answer":"No. The affected claims and subsequent responsibilities remain; the ledger must not remove them to make the choice look costless.","basis":"Theory v2, §14.9.1, with the distinctions explained above."}],"caseLinks":[],"sourceRefs":[{"section":"14.9.1","startLine":3162,"endLine":3169}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-14#section-14-9-1","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§14.9.1; English reading edition, lines 3162–3169","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]}}},"headers":[],"relativePath":"en/theory/part-14.md","filePath":"en/theory/part-14.md"}'),c={name:"en/theory/part-14.md"};function d(l,e,h,p,u,m){const o=a("SectionLesson");return s(),r("div",null,[e[0]||(e[0]=t("",1)),i(o,{section:"14.4.1"}),e[1]||(e[1]=t("",1)),i(o,{section:"14.5"}),e[2]||(e[2]=t("",1)),i(o,{section:"14.9.1"}),e[3]||(e[3]=t("",3))])}const g=n(c,[["render",d]]);export{b as __pageData,g as default};
